1	import { randomBytes } from 'node:crypto';
2	import { mkdir, rm } from 'node:fs/promises';
3	import { homedir, tmpdir } from 'node:os';
4	import { join } from 'node:path';
5	import {
6	  cliFailureState,
7	  readinessDetail,
8	  readinessFailure,
9	  readinessMessage,
10	} from '@graphgoblin/domain';
11	import type { HarnessReadinessState, PromptSubmission } from '@graphgoblin/contracts';
12	import type {
13	  HarnessEvent,
14	  HarnessPreflight,
15	  HarnessPort,
16	  HarnessResult,
17	  HarnessSession,
18	  HarnessStartRequest,
19	} from '@graphgoblin/engine';
20	import { subscriptionEnvironment } from './environment.js';
21	import { ClaudeHarnessError, abortError } from './errors.js';
22	import {
23	  claudePolicy,
24	  policyArgs,
25	  resolvedClaudeSettings,
26	  SUPPRESSION_ARGS,
27	  type ClaudePolicy,
28	} from './policy.js';
29	import {
30	  ClaudeAccumulator,
31	  JsonLines,
32	  authCategory,
33	  validClaudeSessionId,
34	  installedClaudeVersion,
35	  verifyInstalledCapabilities,
36	} from './protocol.js';
37	import { runClaudeProcess, type ClaudeCliRunner, type ClaudeProcessResult } from './process.js';
38	import { EventQueue } from './queue.js';
39	import { claudeModelCapabilities } from './models.js';
40	export interface ClaudeHarnessOptions {
41	  /** User-installed native executable; never installed, downloaded, or substituted by this adapter. */
42	  binary?: string;
43	  env?: NodeJS.ProcessEnv;
44	  platform?: NodeJS.Platform;
45	  preflightTimeoutMs?: number;
46	  maxOutputBytes?: number;
47	  /** Deterministic process transport injection; no provider call is needed for unit tests. */
48	  runner?: ClaudeCliRunner;
49	}
50	export interface ClaudeHarnessPreflight extends HarnessPreflight {
51	  authMethod: 'claude.ai' | null;
52	  supportedPolicies: ClaudePolicy[];
53	}
54	function failureState(error: unknown): Exclude<HarnessReadinessState, 'ready'> {
55	  const failure = error;
56	  if (!(failure instanceof ClaudeHarnessError)) return 'unknown';
57	  switch (failure.code) {
58	    case 'HARNESS_NOT_INSTALLED':
59	      return 'cli-missing';
60	    case 'HARNESS_CLI_INCOMPATIBLE':
61	    case 'HARNESS_UNSUPPORTED_POLICY':
62	      return 'cli-incompatible';
63	    case 'HARNESS_NOT_AUTHENTICATED':
64	      return 'auth';
65	    case 'HARNESS_QUOTA_EXHAUSTED':
66	      return 'quota';
67	    case 'HARNESS_TRANSPORT_FAILED':
68	      return 'transport';
69	    default:
70	      return 'unknown';
71	  }
72	}
73	/** Fresh names tried before a run of name collisions fails the check. */
74	const PROBE_DIRECTORY_ATTEMPTS = 4;
75	/**
76	 * A fresh, exclusively created, empty directory for the version, help and auth checks. Not
77	 * `fs.mkdtemp`: on Windows it hands its prefix to the OS without the long-path namespace and fails
78	 * with ENAMETOOLONG from 248 characters (247 still works), while `mkdir` and starting the CLI there
79	 * still work up to the 258-character working-directory limit (#102,
80	 * docs/qa/2026-10-19-wp-f5-launch-diagnosis.md). A name that already exists is never reused or
81	 * removed; a few fresh names are tried instead.
82	 */
83	async function probeDirectory(): Promise<string> {
84	  for (let attempt = 1; ; attempt += 1) {
85	    const directory = join(tmpdir(), `gg-claude-probe-${randomBytes(4).toString('hex')}`);
86	    try {
87	      await mkdir(directory, { mode: 0o700 });
88	      return directory;
89	    } catch (error) {
90	      if (
91	        (error as NodeJS.ErrnoException).code !== 'EEXIST' ||
92	        attempt === PROBE_DIRECTORY_ATTEMPTS
93	      )
94	        throw error;
95	    }
96	  }
97	}
98	/**
99	 * Turns and no-turn probes share the failure order. A probe's messages are single detail
100	 * sentences about the check (preflight adds the one next step); turn messages are unchanged.
101	 */
102	function checkOutcome(result: ClaudeProcessResult, signal: AbortSignal, probe = false): void {
103	  if (result.terminationUnconfirmed)
104	    throw new ClaudeHarnessError(
105	      'HARNESS_TERMINATION_UNCONFIRMED',
106	      probe
107	        ? 'Claude CLI check process did not confirm that it stopped.'
108	        : 'Claude process termination was not confirmed; stop the installed CLI before retrying',
109	    );
110	  if (signal.aborted || result.aborted) throw abortError();
111	  if (result.spawnCode)
112	    throw new ClaudeHarnessError(
113	      result.spawnCode === 'ENOENT' ? 'HARNESS_NOT_INSTALLED' : 'HARNESS_TURN_FAILED',
114	      !probe
115	        ? 'The installed Claude executable could not be started; check its path and permissions'
116	        : result.spawnCode === 'ENOENT'
117	          ? 'Claude CLI was not found at the configured path.'
118	          : `Claude CLI could not be started (${result.spawnCode}).`,
119	    );
120	  if (result.timedOut)
121	    throw new ClaudeHarnessError(
122	      'HARNESS_TIMEOUT',
123	      probe ? 'Claude CLI did not answer before the check deadline.' : 'Claude process timed out',
124	      true,
125	    );
126	  if (result.overflow)
127	    throw new ClaudeHarnessError(
128	      'HARNESS_OUTPUT_LIMIT',
129	      probe
130	        ? 'Claude CLI printed more output than the check accepts.'
131	        : 'Claude process output exceeded the configured limit',
132	    );
133	  if (result.callbackError) throw result.callbackError;
134	  if (probe && result.exitCode !== 0 && result.failureState && result.failureState !== 'unknown') {
135	    const codes: Partial<
136	      Record<HarnessReadinessState, ConstructorParameters<typeof ClaudeHarnessError>[0]>
137	    > = {
138	      auth: 'HARNESS_NOT_AUTHENTICATED',
139	      quota: 'HARNESS_QUOTA_EXHAUSTED',
140	      transport: 'HARNESS_TRANSPORT_FAILED',
141	      'cli-incompatible': 'HARNESS_CLI_INCOMPATIBLE',
142	    };
143	    throw new ClaudeHarnessError(
144	      codes[result.failureState] ?? 'HARNESS_TURN_FAILED',
145	      readinessDetail('claude', result.failureState),
146	      result.failureState === 'transport',
147	    );
148	  }
149	  if (probe && (result.stdinFailed || result.exitCode !== 0))
150	    throw new ClaudeHarnessError(
151	      'HARNESS_TURN_FAILED',
152	      result.exitCode === null
153	        ? 'Claude CLI check stopped without an exit code.'
154	        : `Claude CLI check exited with code ${result.exitCode}.`,
155	    );
156	  if (result.stdinFailed || result.exitCode !== 0)
157	    throw new ClaudeHarnessError('HARNESS_TURN_FAILED', 'Claude turn failed');
158	}
159	/** Structural current HarnessPort implementation; additive HarnessId integration follows the issue 98 cutover. */
160	export class ClaudeHarness implements HarnessPort {
161	  readonly id = 'claude' as const;
162	  private readonly binary: string;
163	  private readonly runner: ClaudeCliRunner;
164	  private readonly platform: NodeJS.Platform;
165	  private readonly environment: NodeJS.ProcessEnv;
166	  constructor(private readonly options: ClaudeHarnessOptions = {}) {
167	    this.binary =
168	      options.binary ??
169	      join(
170	        options.env?.USERPROFILE ?? process.env.USERPROFILE ?? homedir(),
171	        '.local',
172	        'bin',
173	        'claude.exe',
174	      );
175	    this.runner = options.runner ?? runClaudeProcess;
176	    this.platform = options.platform ?? process.platform;
177	    this.environment = subscriptionEnvironment(options.env ?? process.env);
178	    for (const value of [options.preflightTimeoutMs, options.maxOutputBytes])
179	      if (value !== undefined && (!Number.isSafeInteger(value) || value <= 0))
180	        throw new ClaudeHarnessError(
181	          'HARNESS_INVALID_CONFIGURATION',
182	          'Claude process bounds must be positive integers',
183	        );
184	  }
185	  private supportedPolicies(): ClaudePolicy[] {
186	    return (['read-only', 'danger-full-access'] as const).map((sandbox) =>
187	      claudePolicy({ sandbox, approval: 'never' }, undefined, this.platform),
188	    );
189	  }
190	  private async inspect(signal: AbortSignal): Promise<{
191	    facts: ClaudeHarnessPreflight;
192	    failures: unknown[];
193	  }> {
194	    const facts: ClaudeHarnessPreflight = {
195	      state: 'unknown',
196	      ok: false,
197	      problems: [],
198	      authMethod: null,
199	      models: claudeModelCapabilities(),
200	      supportedPolicies: [],
201	    };
202	    const failures: unknown[] = [];
203	    // Unsupported platforms cannot execute this native Windows adapter.
204	    facts.supportedPolicies = this.supportedPolicies();
205	    const cwd = await probeDirectory();
206	    const run = async (args: string[], authStatus = false): Promise<string> => {
207	      if (signal.aborted) throw abortError();
208	      const result = await this.runner({
209	        binary: this.binary,
210	        args,
211	        cwd,
212	        env: this.environment,
213	        signal,
214	        timeoutMs: this.options.preflightTimeoutMs ?? 15000,
215	        maxOutputBytes: 128 * 1024,
216	        classifyDiagnostics: true,
217	      });
218	      // Auth status can confirm sign-out in JSON or text, even on exit 0. Interpret it only here;
219	      // timeout/start/termination failures remain authoritative and turn output is never inferred.
220	      let auth: unknown;
221	      if (authStatus) {
222	        try {
223	          auth = JSON.parse(result.stdout);
224	        } catch {
225	          /* No structured status. */
226	        }
227	      }
228	      let signOutDetail: string | undefined;
229	      if (
230	        typeof auth === 'object' &&
231	        auth !== null &&
232	        (('loggedIn' in auth && auth.loggedIn === false) ||
233	          ('authMethod' in auth &&
234	            typeof auth.authMethod === 'string' &&
235	            auth.authMethod !== '' &&
236	            auth.authMethod !== 'claude.ai'))
237	      ) {
238	        signOutDetail =
239	          'loggedIn' in auth && auth.loggedIn === false
240	            ? 'Claude is not signed in.'
241	            : 'Claude is not signed in with a Claude.ai account.';
242	      }
243	      if (
244	        authStatus &&
245	        (signOutDetail || /\bnot logged in\b/i.test(result.stdout) || result.notLoggedIn)
246	      ) {
247	        checkOutcome({ ...result, exitCode: 0 }, signal, true);
248	        facts.authenticated = false;
249	        throw new ClaudeHarnessError(
250	          'HARNESS_NOT_AUTHENTICATED',
251	          signOutDetail ?? 'Claude is not signed in.',
252	        );
253	      }
254	      // This path runs version/help/auth only; stdout cannot be a model response.
255	      // Recognised stderr is the CLI's primary error evidence, including conflicts with stdout.
256	      // An unrelated warning must not hide a recognised stdout failure. Turn stdout is untouched.
257	      checkOutcome(
258	        {
259	          ...result,
260	          failureState:
261	            !result.failureState || result.failureState === 'unknown'
262	              ? cliFailureState(result.stdout)
263	              : result.failureState,
264	        },
265	        signal,
266	        true,
267	      );
268	      return result.stdout;
269	    };
270	    try {
271	      const versionText = await run([...SUPPRESSION_ARGS, '--version']);
272	      const version = installedClaudeVersion(versionText);
273	      if (version !== undefined) facts.version = version;
274	      // --max-turns is a hidden CLI option. Parse it alongside --help without starting a turn.
275	      let help: string;
276	      try {
277	        help = await run([...SUPPRESSION_ARGS, '--max-turns', '1', '--help']);
278	      } catch (error) {
279	        // A rejected or failing option check names the version; timeouts and causes keep their detail.
280	        if (
281	          error instanceof ClaudeHarnessError &&
282	          (error.code === 'HARNESS_CLI_INCOMPATIBLE' || error.code === 'HARNESS_TURN_FAILED')
283	        )
284	          throw new ClaudeHarnessError(
285	            error.code,
286	            `Claude CLI ${version ?? '(unknown version)'} failed the --max-turns/--help check.`,
287	            error.retriable,
288	          );
289	        throw error;
290	      }
291	      verifyInstalledCapabilities(versionText, help);
292	    } catch (error) {
293	      failures.push(error);
294	    }
295	    // Login is a separate fact, even when the CLI version or policy flags are unsupported.
296	    try {
297	      const auth = await run([...SUPPRESSION_ARGS, 'auth', 'status', '--json'], true);
298	      facts.authMethod = authCategory(auth);
299	      if (facts.authMethod === null)
300	        throw new ClaudeHarnessError('HARNESS_TURN_FAILED', readinessDetail('claude', 'unknown'));
301	      facts.authenticated = true;
302	    } catch (error) {
303	      if (failureState(error) === 'auth') facts.authenticated = false;
304	      failures.push(error);
305	    }
306	    try {
307	      await rm(cwd, { recursive: true, force: true });
308	    } catch {
309	      // Cleanup must not hide a still-running native process or another prerequisite failure.
310	      if (!failures.length)
311	        failures.push(
312	          new ClaudeHarnessError(
313	            'HARNESS_TURN_FAILED',
314	            'Claude readiness check could not remove its temporary folder.',
315	          ),
316	        );
317	    }
318	    facts.ok = failures.length === 0;
319	    facts.state = facts.ok ? 'ready' : failureState(failures[0]);
320	    // One problem per failure: its own detail sentence and the action for its state.
321	    // Anything other than a typed harness error keeps the generic detail, never its message.
322	    facts.problems = [
323	      ...new Set(
324	        failures.map((error) =>
325	          readinessMessage(
326	            'claude',
327	            failureState(error),
328	            error instanceof ClaudeHarnessError ? error.message : undefined,
329	          ),
330	        ),
331	      ),
332	    ];
333	    return { facts, failures };
334	  }
335	  async preflight(): Promise<ClaudeHarnessPreflight> {
336	    try {
337	      return (await this.inspect(new AbortController().signal)).facts;
338	    } catch (error) {
339	      return {
340	        ...readinessFailure('claude', failureState(error)),
341	        authMethod: null,
342	        models: claudeModelCapabilities(),
343	        supportedPolicies: this.platform === 'win32' ? this.supportedPolicies() : [],
344	      };
345	    }
346	  }
347	  start(request: HarnessStartRequest, signal: AbortSignal): HarnessSession {
348	    return this.turn(request, signal);
349	  }
350	  resume(sessionId: string, request: HarnessStartRequest, signal: AbortSignal): HarnessSession {
351	    return this.turn(request, signal, sessionId);
352	  }
353	  private turn(
354	    request: HarnessStartRequest,
355	    signal: AbortSignal,
356	    resumeId?: string,
357	  ): HarnessSession {
358	    const controller = new AbortController();
359	    const abort = () => controller.abort();
360	    if (signal.aborted) abort();
361	    else signal.addEventListener('abort', abort, { once: true });
362	    const queue = new EventQueue<HarnessEvent>();
363	    let closed = false;
364	    let resolveId!: (id: string) => void, rejectId!: (error: unknown) => void;
365	    const sessionId = new Promise<string>((resolve, reject) => {
366	      resolveId = resolve;
367	      rejectId = reject;
368	    });
369	    sessionId.catch(() => undefined);
370	    const pump = async (): Promise<HarnessResult> => {
371	      let detectedVersion: string | undefined;
372	      let delivery: PromptSubmission = 'definitely-not-submitted';
373	      let accepted = false;
374	      let initialized = false;
375	      try {
376	        if (controller.signal.aborted) throw abortError();
377	        if (resumeId !== undefined && !validClaudeSessionId(resumeId))
378	          throw new ClaudeHarnessError(
379	            'HARNESS_INVALID_CONFIGURATION',
380	            'Claude resume requires a valid native session id',
381	          );
382	        const policy = claudePolicy(request.options, request.capabilities, this.platform);
383	        const settings = resolvedClaudeSettings(request);
384	        const inspection = await this.inspect(controller.signal);
385	        if (!inspection.facts.ok) throw inspection.failures[0];
386	        detectedVersion = inspection.facts.version;
387	        const accumulator = new ClaudeAccumulator({
388	          policy,
389	          model: settings.model,
390	          effort: settings.effort,
391	          mode: resumeId ? 'resumed' : 'fresh',
392	          ...(resumeId ? { resumeId } : {}),
393	          ...(request.turn.outputSchema ? { schema: request.turn.outputSchema } : {}),
394	        });
395	        const parser = new JsonLines();
396	        let completionEvents: HarnessEvent[] = [];
397	        const accept = (record: Record<string, unknown>): void => {
398	          // Native missing-session refusals can precede init (CLI 2.1.304). They are not
399	          // turn output. Await the fixed stderr refusal; never retain the provider error body.
400	          if (
401	            !initialized &&
402	            !accepted &&
