        cwd: dir,
        env: subscriptionEnvironment(),
        signal: controller.signal,
        timeoutMs: 5000,
        maxOutputBytes: 1024,
      },
      (chunk) => {
        stdout += chunk.toString();
        if (stdout.includes('ready')) announce();
      },
    );
