2	import { tmpdir } from 'node:os';
3	import { fileURLToPath } from 'node:url';
4	import type { HarnessEvent } from '@graphgoblin/engine';
5	import { ClaudeHarness } from './harness.js';
6	import { runClaudeProcess } from './process.js';
7	
8	const id = '11111111-1111-4111-8111-111111111111';
9	describe('Claude submission evidence through a fake CLI process', () => {
10	  it.each(['pre-start', 'arguments', 'auth', 'init', 'assistant', 'missing'] as const)(
11	    '%s reports only truthful delivery evidence',
12	    async (scenario) => {
13	      const harness = new ClaudeHarness({
14	        platform: 'win32',
15	        runner: (request, onStdout) =>
16	          runClaudeProcess(
17	            {
18	              ...request,
19	              binary:
20	                scenario === 'pre-start' && request.stdin !== undefined
21	                  ? 'gg-wp-f4-nonexistent.exe'
22	                  : process.execPath,
23	              args: [
24	                fileURLToPath(new URL('./fixtures/turn-cli.mjs', import.meta.url)),
25	                scenario,
26	                ...request.args,
27	              ],
28	            },
29	            onStdout,
30	          ),
31	      });
32	      const request = {
33	        workingDirectory: tmpdir(),
34	        model: 'claude-opus-5-5',
35	        effort: 'high' as const,
36	        options: { sandbox: 'read-only' as const, approval: 'never' as const },
37	        turn: { prompt: 'synthetic authored task' },
38	      };
39	      const session =
40	        scenario === 'missing'
41	          ? harness.resume(id, request, new AbortController().signal)
42	          : harness.start(request, new AbortController().signal);
43	      const events: HarnessEvent[] = [];
44	      for await (const event of session.events) events.push(event);
45	      await expect(session.result).rejects.toThrow();
46	      expect(events.filter((x) => x.type === 'submitted')).toEqual(
47	        scenario === 'assistant' ? [{ type: 'submitted', marker: 'claude.assistant' }] : [],
48	      );
49	      expect(events.at(-1)).toMatchObject({
50	        type: 'error',
51	        submission:
52	          scenario === 'missing'
53	            ? 'session-missing'
54	            : ['pre-start', 'arguments', 'auth'].includes(scenario)
55	              ? 'definitely-not-submitted'
56	              : 'delivery-uncertain',
57	      });
58	      if (scenario === 'missing') {
59	        expect(events.at(-1)).toMatchObject({ code: 'HARNESS_SESSION_MISSING' });
60	        expect(events.some((x) => x.type === 'session')).toBe(false);
61	      }
62	      if (scenario === 'auth')
