// Records only error code/errno/syscall, whether error.path names the binary, and stat outcomes.
import { spawn } from 'node:child_process';
import { mkdtemp, mkdir, writeFile, stat, rm, realpath } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join, resolve, sep } from 'node:path';

const root = await mkdtemp(join(tmpdir(), 'gg-364-native-'));
const results = [];
function start(binary, cwd) {
  return new Promise((done) => {
    let child;
    try {
      child = spawn(binary, ['-e', 'process.stdout.write(process.cwd().length+"")'], { cwd, windowsHide: true, shell: false, stdio: ['pipe', 'pipe', 'pipe'] });
    } catch (error) {
      done({ threw: true, code: error.code ?? null });
      return;
    }
    let out = '';
    child.stdout.on('data', (c) => (out += c));
    child.on('error', (error) => done({ event: 'error', code: error.code ?? null, errno: error.errno ?? null, syscall: error.syscall ?? null, errorPathIsBinary: error.path === binary, errorPathIsCwd: error.path === cwd }));
    child.on('close', (code) => done({ event: 'close', exitCode: code, childCwdLength: Number(out) || null }));
    child.stdin.end();
  });
}
async function observe(path) {
