        ...(spawnCode ? { spawnCode } : {}),
        ...(exitCode !== 0 && rejection ? { turnRejection: rejection } : {}),
        ...(stdinFailed ? { stdinFailed } : {}),
        ...(callbackError ? { callbackError } : {}),
