import type { HarnessReadinessState } from '@graphgoblin/contracts';
export interface ClaudeProcessRequest {
  binary: string;
  args: readonly string[];
  cwd: string;
  env: NodeJS.ProcessEnv;
  stdin?: string;
  signal: AbortSignal;
