          ? { notLoggedIn: true }
          : {}),
      });
    };
    const kill = (): void => {
      if (settled) return;
      clearTimeout(timer);
      if (killing) return;
      killTimer = setTimeout(() => finish(null, true), 5000);
      killing = killTree(child);
      void killing.then((confirmed) => {
        if (!confirmed) finish(null, true);
        else {
          treeConfirmed = true;
          if (closed) finish(closeCode);
        }
      });
    };
    const timer =
