/** Windows starts no process in a working directory longer than this (#102, #364). */
const WINDOWS_WORKING_DIRECTORY_LIMIT = 258;
/**
 * A refused start, worded from what the runner established (#364). A spawn `ENOENT` alone does not
 * say whether the executable or the working directory failed, so only an established absence is
 * reported as a missing CLI, and only the turn's own working directory is configuration; the
 * temporary check folder is not. Otherwise the cause stays unknown and the message says so,
 * naming the Windows path limit only as a fact about the path's length. Messages are fixed text.
 */
function startFailure(result: ClaudeProcessResult, cwd: string, probe: boolean): ClaudeHarnessError {
  const code = result.spawnCode ?? 'UNKNOWN';
  if (result.startRefusal === 'executable-missing')
    return new ClaudeHarnessError(
      'HARNESS_NOT_INSTALLED',
      probe
        ? 'Claude CLI was not found at the configured path.'
        : 'The Claude executable was not found at its configured path; install the Claude CLI or correct its path',
    );
  if (result.startRefusal) {
    const state =
      result.startRefusal === 'working-directory-missing' ? 'does not exist' : 'is not a folder';
    return probe
      ? new ClaudeHarnessError(
          'HARNESS_TURN_FAILED',
          `Claude CLI could not be started because its temporary check folder ${state}.`,
        )
      : new ClaudeHarnessError(
          'HARNESS_INVALID_CONFIGURATION',
          `Claude could not be started because the working directory ${state}; check the working directory setting`,
        );
  }
  const long = resolve(cwd).length > WINDOWS_WORKING_DIRECTORY_LIMIT;
  if (probe)
    return new ClaudeHarnessError(
      'HARNESS_TURN_FAILED',
      long
        ? `Claude CLI could not be started (${code}) from its temporary check folder, whose path is longer than the ${WINDOWS_WORKING_DIRECTORY_LIMIT} characters Windows allows for a working directory; check TEMP and TMP.`
        : `Claude CLI could not be started (${code}).`,
    );
  return new ClaudeHarnessError(
    'HARNESS_TURN_FAILED',
    long
      ? `Claude could not be started (${code}); the working directory path is longer than the ${WINDOWS_WORKING_DIRECTORY_LIMIT} characters Windows allows for a working directory`
      : `The installed Claude executable could not be started (${code}); check its path and permissions, and that the working directory exists`,
