      sessionId,
      events: queue,
      result,
      cancel: () => {
        if (closed)
          return result.then(
            () => undefined,
            (error: unknown) => {
              if (
                error instanceof ClaudeHarnessError &&
                error.code === 'HARNESS_TERMINATION_UNCONFIRMED'
              )
                throw error;
            },
          );
        cancellation ??= (async () => {
          controller.abort();
          await result.catch((error: unknown) => {
            if (
              error instanceof ClaudeHarnessError &&
              error.code === 'HARNESS_TERMINATION_UNCONFIRMED'
            )
              throw error;
          });
        })();
        return cancellation;
      },
    };
  }
}

