  usage: { input_tokens: 2, output_tokens: 3 },
  modelUsage: { 'claude-opus-5-5': {} },
};
const outcome = (stdout = '', extra: Partial<ClaudeProcessResult> = {}): ClaudeProcessResult => ({
  stdout,
  exitCode: 0,
  aborted: false,
  timedOut: false,
  overflow: false,
